export const CIF_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/cif-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getCifStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(CIF_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
